import 'package:enviroo/layouts/balance.dart';
import 'package:enviroo/screens/nasabah/list_bagi_hasil_nasabah_screen.dart';
import 'package:enviroo/layouts/informasi_layouts.dart';
import 'package:enviroo/layouts/jadwal_layouts.dart';
import 'package:enviroo/layouts/menu_layouts.dart';
import 'package:enviroo/providers/auth_provider.dart';
import 'package:enviroo/providers/konten_provider.dart';
import 'package:enviroo/screens/katalog_screen.dart';
import 'package:enviroo/services/reward_overview_service.dart';
import 'package:enviroo/layouts/transaksi_layouts.dart';
import 'package:enviroo/widgets/filter_chip_row.dart';
import 'package:enviroo/widgets/navbar.dart';
import 'package:enviroo/widgets/topbar_custom.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:provider/provider.dart';

class HomeScreen extends StatefulWidget {
  const HomeScreen({Key? key}) : super(key: key);
  
  @override
  State<HomeScreen> createState() => _HomeScreenState();
}


class _HomeScreenState extends State<HomeScreen> {
  int _selectedNavIndex = 0;
  final _jadwalKey = GlobalKey<JadwalSetoranSectionState>();
  


  @override
  void initState() {
    super.initState();
    // Fetch profile data when home screen initializes
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final auth = Provider.of<AuthProvider>(context, listen: false);
      if (auth.role == 'nasabah') {
        auth.fetchNasabahProfile();

        // Fetch konten informasi too
        if (auth.bankId != null) {
          Provider.of<KontenProvider>(context, listen: false).fetchKonten(
            auth.bankId!,
            published: true,
          );
        }
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Consumer<AuthProvider>(
      builder: (context, auth, _) {
        return Scaffold(
          backgroundColor: Color(0xFFEAF8E7),
          body: SafeArea(
            child: Column(
              children: [
                const TopBarCustom(),
                MainNavbar(
                  selectedIndex: _selectedNavIndex,
                  onTabChanged: (index) {
                    setState(() => _selectedNavIndex = index);
                    if (index == 0) {
                      WidgetsBinding.instance.addPostFrameCallback((_) {
                        if (!mounted) return;
                        _jadwalKey.currentState?.refresh();
                        final auth = Provider.of<AuthProvider>(context, listen: false);
                        if (auth.bankId != null) {
                          Provider.of<KontenProvider>(context, listen: false).fetchKonten(
                            auth.bankId!,
                            published: true,
                          );
                        }
                      });
                    } else if (index == 2 && _rewardFetched) {
                      _fetchRewardOverview();
                    }
                  },
                ),
                Expanded(
                  child: _selectedNavIndex == 0
                      ? RefreshIndicator(
                          color: const Color(0xFF4EA771),
                          onRefresh: () async {
                            final auth = Provider.of<AuthProvider>(context, listen: false);
                            await Future.wait([
                              _jadwalKey.currentState?.refresh() ?? Future.value(),
                              if (auth.bankId != null)
                                Provider.of<KontenProvider>(context, listen: false).fetchKonten(
                                  auth.bankId!,
                                  published: true,
                                ),
                            ]);
                          },
                          child: SingleChildScrollView(
                            physics: const AlwaysScrollableScrollPhysics(),
                            child: _buildHomeLayouts(),
                          ),
                        )
                      : _selectedNavIndex == 1
                      ? const TransaksiLayouts()
                      : _buildRewardLayouts(),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  Widget _buildHomeLayouts() {
    return Column(
      children: [
        SizedBox(height: 10),
        BalanceLayouts(),
        MainMenu(),
        JadwalSetoranSection(key: _jadwalKey),
        InformasiSection(),
        SizedBox(height: 50),
      ],
    );
  }

  bool _rewardLoading = true;
  String? _rewardError;
  // New structure: separate lists per reward type
  List<Map<String, dynamic>> _rewardUang = [];
  List<Map<String, dynamic>> _rewardSembako = [];
  bool _rewardFetched = false;

  Future<void> _fetchRewardOverview() async {
    final auth = Provider.of<AuthProvider>(context, listen: false);
    final nasabahId = auth.identityId;
    if (nasabahId == null) return;

    setState(() {
      _rewardLoading = true;
      _rewardError = null;
    });

    final result = await RewardOverviewService.getRewardOverview(nasabahId);

    if (!mounted) return;
    if (result['success'] == true && result['data'] != null) {
      final data = result['data'] as Map<String, dynamic>;
      setState(() {
        _rewardUang = List<Map<String, dynamic>>.from(data['uang'] ?? []);
        _rewardSembako = List<Map<String, dynamic>>.from(data['sembako'] ?? []);
        _rewardLoading = false;
        _rewardFetched = true;
      });
    } else {
      setState(() {
        _rewardError = result['message'] ?? 'Gagal memuat data reward';
        _rewardLoading = false;
        _rewardFetched = true;
      });
    }
  }

  Widget _buildRewardLayouts() {
    if (!_rewardFetched) {
      WidgetsBinding.instance.addPostFrameCallback((_) => _fetchRewardOverview());
    }

    if (_rewardLoading) {
      return const Center(
        child: CircularProgressIndicator(color: Color(0xFF4EA771)),
      );
    }

    if (_rewardError != null) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(32),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              const Icon(Icons.error_outline_rounded, color: Colors.redAccent, size: 48),
              const SizedBox(height: 12),
              Text(
                _rewardError!,
                textAlign: TextAlign.center,
                style: const TextStyle(fontFamily: 'Poppins', fontSize: 13),
              ),
              const SizedBox(height: 16),
              ElevatedButton(
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF4EA771),
                  foregroundColor: Colors.white,
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(50)),
                ),
                onPressed: () {
                  _rewardFetched = false;
                  _fetchRewardOverview();
                },
                child: const Text('Coba lagi'),
              ),
            ],
          ),
        ),
      );
    }

    return SingleChildScrollView(
      physics: const BouncingScrollPhysics(),
      padding: const EdgeInsets.fromLTRB(20, 20, 20, 40),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Padding(
            padding: EdgeInsets.symmetric(horizontal: 10),
            child: Text(
              'Program Bagi Hasil',
              style: TextStyle(
                fontFamily: 'Poppins',
                fontSize: 15,
                fontWeight: FontWeight.w700,
                color: Color(0xFF013236),
              ),
            ),
          ),
          const SizedBox(height: 4),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 10),
            child: Text(
              'Pilih reward yang ingin kamu lihat riwayat bagi hasilnya.',
              style: TextStyle(
                fontFamily: 'Poppins',
                fontSize: 12,
                color: const Color(0xFF013236).withOpacity(0.55),
                height: 1.5,
              ),
            ),
          ),

          const SizedBox(height: 20),

          ..._rewardUang.isNotEmpty
              ? _rewardUang.map((r) => _RewardCard(rewardData: r, type: _RewardType.uang))
              : [const _RewardCard(rewardData: {}, type: _RewardType.uang, notAvailable: true)],
          ..._rewardSembako.isNotEmpty
              ? _rewardSembako.map((r) => _RewardCard(rewardData: r, type: _RewardType.sembako))
              : [const _RewardCard(rewardData: {}, type: _RewardType.sembako, notAvailable: true)],
        ],
      ),
    );
  }
}

