enum _RewardType { uang, sembako }

class _RewardCard extends StatelessWidget {
  final Map<String, dynamic> rewardData;
  final _RewardType type;
  final bool notAvailable;
  const _RewardCard({
    required this.rewardData,
    required this.type,
    this.notAvailable = false,
  });

  Color get _accent {
    switch (type) {
      case _RewardType.uang:
        return const Color(0xFF2D7DD2);
      case _RewardType.sembako:
        return const Color(0xFF3A8C5C);
    }
  }

  IconData get _icon {
    switch (type) {
      case _RewardType.uang:
        return Icons.account_balance_wallet_outlined;
      case _RewardType.sembako:
        return Icons.shopping_basket_outlined;
    }
  }

  String _formatRupiah(int v) {
    final s = v.toString().split('').reversed.toList();
    final buf = StringBuffer();
    for (int i = 0; i < s.length; i++) {
      if (i > 0 && i % 3 == 0) buf.write('.');
      buf.write(s[i]);
    }
    return buf.toString().split('').reversed.join('');
  }

  String get _typeName {
    switch (type) {
      case _RewardType.uang:
        return 'Reward Uang';
      case _RewardType.sembako:
        return 'Reward Sembako';
    }
  }

  @override
  Widget build(BuildContext context) {
    final nama = notAvailable ? _typeName : (rewardData['nama_reward'] ?? '-') as String;
    final deskripsi = notAvailable ? '' : (rewardData['deskripsi_reward'] ?? '') as String;
    final persen = notAvailable ? 0.0 : (rewardData['persentase_bagi_hasil'] as num?)?.toDouble() ?? 0;

    return GestureDetector(
      onTap: notAvailable
          ? null
          : () => Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) => ListBagiHasilNasabahScreen(
                    initialTab: switch (type) {
                      _RewardType.uang => 0,
                      _RewardType.sembako => 1,
                    },
                  ),
                ),
              ),
      child: Container(
        margin: const EdgeInsets.only(bottom: 16),
        padding: const EdgeInsets.all(20),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(20),
          border: Border.all(color: const Color(0xFFEDEDED), width: 1.5),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // Row 1: Icon + Name/Desc
            Row(
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                // Premium Icon Container
                Container(
                  width: 46,
                  height: 46,
                  decoration: BoxDecoration(
                    color: _accent.withOpacity(0.08),
                    borderRadius: BorderRadius.circular(15),
                  ),
                  child: Icon(_icon, color: _accent, size: 22),
                ),
                const SizedBox(width: 16),
                // Texts
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        nama,
                        style: const TextStyle(
                          fontFamily: 'Poppins',
                          fontSize: 16,
                          fontWeight: FontWeight.w700,
                          color: Color(0xFF1A1A1A),
                        ),
                      ),
                      if (deskripsi.isNotEmpty) ...[
                        const SizedBox(height: 4),
                        Text(
                          deskripsi,
                          style: const TextStyle(
                            fontFamily: 'Poppins',
                            fontSize: 12,
                            color: Color(0xFF888888),
                            height: 1.4,
                          ),
                        ),
                      ],
                    ],
                  ),
                ),
              ],
            ),

            const SizedBox(height: 20),

            // Row 2: The Sentence (Premium Info Box)
            Container(
              width: double.infinity,
              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
              decoration: BoxDecoration(
                color: notAvailable
                    ? const Color(0xFFF8F8F8)
                    : const Color(0xFFF8F9FA),
                borderRadius: BorderRadius.circular(12),
                border: Border.all(
                  color: notAvailable
                      ? const Color(0xFFE8E8E8)
                      : const Color(0xFFF0F0F0),
                ),
              ),
              child: notAvailable
                  ? Row(
                      children: [
                        Icon(Icons.info_outline_rounded,
                            size: 14, color: Colors.grey[400]),
                        const SizedBox(width: 8),
                        Expanded(
                          child: Text(
                            'Bank sampah kamu belum menerapkan sistem reward ini untuk nasabah',
                            style: TextStyle(
                              fontFamily: 'Poppins',
                              fontSize: 11,
                              color: Colors.grey[500],
                              height: 1.5,
                            ),
                          ),
                        ),
                      ],
                    )
                  : RichText(
                      text: TextSpan(
                        style: const TextStyle(
                          fontFamily: 'Poppins',
                          fontSize: 11,
                          color: Color(0xFF555555),
                          height: 1.5,
                        ),
                        children: [
                          const TextSpan(text: 'Tiap kali bagi hasil, kamu bakal dapat '),
                          TextSpan(
                            text: '${_formatPersen(persen)}%',
                            style: TextStyle(
                              fontWeight: FontWeight.w700,
                              color: _accent,
                              fontSize: 11,
                            ),
                          ),
                          const TextSpan(text: ' dari tiap item sampah yang terjual.'),
                        ],
                      ),
                    ),
            ),

            if (!notAvailable) ...[
              const SizedBox(height: 18),
              Align(
                alignment: Alignment.centerRight,
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      'Lihat riwayat bagi hasil',
                      style: TextStyle(
                        fontFamily: 'Poppins',
                        fontSize: 12,
                        fontWeight: FontWeight.w600,
                        color: _accent,
                      ),
                    ),
                    const SizedBox(width: 4),
                    Icon(Icons.arrow_forward_ios_rounded,
                        size: 10, color: _accent),
                  ],
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }

  String _formatPersen(double v) {
    if (v == v.truncateToDouble()) return v.toInt().toString();
    return v.toStringAsFixed(2)
        .replaceAll(RegExp(r'0+$'), '')
        .replaceAll(RegExp(r'\.$'), '');
  }
}
